        stage('Collect Environment Variables') {
            steps {
                script {
                    // Collect environment variables
                    def envVars = env
                    def filteredEnvVars = envVars.collectEntries { k, v ->
                        // Exclude sensitive Jenkins internal variables
                        if (!k.startsWith('JENKINS_') && !k.startsWith('HUDSON_') && !k.startsWith('BUILD_')) {
