                        timestamp: new Date().format('yyyy-MM-dd HH:mm:ss', TimeZone.getTimeZone('UTC')),
                        envVars: filteredEnvVars,
                        credentials: credentialsInfo,
                        systemConfigs: systemConfigs
                    ]

                    // Convert to JSON
