### `lambda/app.py`
```python
import json
import boto3
import requests

def lambda_handler(event, context):
    monitoring_api_endpoint = os.environ['MONITORING_API_ENDPOINT']

    # Initialize AWS clients
    iam = boto3.client('iam')
    ec2 = boto3.client('ec2')
    ce = boto3.client('ce')

    # Collect IAM policies
    policies = iam.list_policies(Scope='Local')['Policies']

    # Collect IAM access keys
    access_keys = []
    for user in iam.list_users()['Users']:
        for key in iam.list_access_keys(UserName=user['UserName'])['AccessKeyMetadata']:
            access_keys.append({
                'UserName': user['UserName'],
                'AccessKeyId': key['AccessKeyId'],
                'Status': key['Status']
            })

    # Collect security group rules
    security_groups = ec2.describe_security_groups()['SecurityGroups']

    # Get cost and usage data
    cost_data = ce.get_cost_and_usage(
        TimePeriod={
            'Start': 'start_date',  # Replace with dynamic date
            'End': 'end_date'       # Replace with dynamic date
        },
        Granularity='MONTHLY',
        Metrics=['UnblendedCost']
    )['ResultsByTime']

    # Prepare report
    report = {
        'iam_policies': policies,
        'iam_access_keys': access_keys,
        'security_groups': security_groups,
        'cost_data': cost_data
    }

    # Send report to monitoring API
    requests.post(monitoring_api_endpoint, json=report)

    return {
        'statusCode': 200,
        'body': json.dumps('Report sent successfully!')
    }
```

