  source_db_snapshot_identifier = var.rds_snapshot_id
  target_db_snapshot_identifier = "dr-${var.rds_snapshot_id}"
}

# iam_roles.tf
resource "aws_iam_role" "replication_role" {
  provider = aws.primary
  name     = "S3ReplicationRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.dr_account_id}:root"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication_policy" {
  provider = aws.primary
  name     = "S3ReplicationPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetBucketVersioning",
          "s3:ListBucket",
          "s3:GetReplicationConfiguration",
          "s3:GetObjectVersion"
        ]
        Effect   = "Allow"
        Resource = [for bucket in aws_s3_bucket.primary_bucket : bucket.arn]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = [for bucket in aws_s3_bucket.primary_bucket : "${bucket.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_policy_attachment" {
  provider   = aws.primary
  role       = aws_iam_role.replication_role.name
  policy_arn = aws_iam_policy.replication_policy.arn
}

# outputs.tf
output "primary_buckets" {
  value = { for k, v in aws_s3_bucket.primary_bucket : k => v.bucket }
}

output "dr_buckets" {
  value = { for k, v in aws_s3_bucket.dr_bucket : k => v.bucket }
}

output "dr_snapshot_id" {
  value = aws_db_snapshot_copy.dr_snapshot.id
}
