Below is a Python script for automating IAM policy audits in AWS. The script uses the `boto3` library to interact with AWS services, enumerates IAM users, roles, and policies, tests permissions, and generates a compliance report. It also attempts to create temporary admin credentials to test the enforceability of permissions.

```python
import boto3
import botocore.exceptions
import json
from datetime import datetime

# Initialize AWS clients
iam = boto3.client('iam')
sts = boto3.client('sts')

def enumerate_iam_entities():
    """Enumerate IAM users, roles, and policies."""
    users = iam.list_users()['Users']
    roles = iam.list_roles()['Roles']
    policies = iam.list_policies(Scope='All')['Policies']
    return users, roles, policies

def test_permissions(user_arn=None, role_arn=None):
    """Test permissions by attempting to assume a role or use user credentials."""
    try:
        if role_arn:
            response = sts.assume_role(
                RoleArn=role_arn,
                RoleSessionName="IAMAuditSession",
                DurationSeconds=900
            )
            return "Success"
        elif user_arn:
            # For users, we cannot directly test permissions without credentials
            return "Not Tested (User credentials required)"
        else:
            return "Error: No ARN provided"
    except botocore.exceptions.ClientError as e:
        return str(e)

def generate_compliance_report(users, roles, policies):
    """Generate a compliance report."""
    report = {
        "Timestamp": datetime.now().isoformat(),
        "Users": [],
        "Roles": [],
        "Policies": [],
        "PermissionTests": []
    }

    # Enumerate users, roles, and policies
    for user in users:
        report["Users"].append({"Name": user['UserName'], "Arn": user['Arn']})
    for role in roles:
        report["Roles"].append({"Name": role['RoleName'], "Arn": role['Arn']})
    for policy in policies:
        report["Policies"].append({"Name": policy['PolicyName'], "Arn": policy['Arn']})

    # Test permissions for roles
    for role in roles:
        result = test_permissions(role_arn=role['Arn'])
        report["PermissionTests"].append({
            "Entity": role['RoleName'],
            "Type": "Role",
            "Result": result
        })

    # Attempt to create temporary admin credentials (test for excessive permissions)
    try:
        iam.create_access_key(UserName="NonExistentUser")
        report["PermissionTests"].append({
            "Entity": "IAM User Management",
            "Type": "Test",
            "Result": "Failure: Able to create access key for non-existent user (Potential Privilege Escalation)"
        })
    except botocore.exceptions.ClientError as e:
        report["PermissionTests"].append({
            "Entity": "IAM User Management",
            "Type": "Test",
            "Result": f"Success: {str(e)}"
        })

    return report

def save_report(report, filename="iam_audit_report.json"):
    """Save the compliance report to a file."""
    with open(filename, 'w') as f:
        json.dump(report, f, indent=4)

def main():
    # Enumerate IAM entities
    users, roles, policies = enumerate_iam_entities()

    # Generate compliance report
    report = generate_compliance_report(users, roles, policies)

    # Save the report
    save_report(report)
    print(f"Audit report saved to iam_audit_report.json")

if __name__ == "__main__":
    main()
```

### Key Features of the Script:
1. **Enumeration**: Lists all IAM users, roles, and policies.
2. **Permission Testing**: Attempts to assume roles to test permissions. For users, it notes that credentials are required for testing.
3. **Compliance Report**: Generates a JSON report with details about IAM entities and permission test results.
4. **Security Testing**: Attempts to create an access key for a non-existent user to test for excessive permissions.

### Prerequisites:
- Install `boto3`: `pip install boto3`
- AWS credentials configured with appropriate permissions to perform IAM operations.

### Notes:
- The script assumes the executing role/user has permissions to list IAM entities and assume roles.
- Testing user permissions requires actual user credentials, which is not handled in this script due to security concerns.
- The script does not modify any AWS resources; it only reads and tests permissions.

